	private static BindingSet input() {
		return BindingSetOrigin.optimizationInput(EmptyBindingSet.getInstance());
	}

	private static QueryRoot queryRoot(String query) {
		TupleExpr parsed = parse(query);
		return parsed instanceof QueryRoot root ? root : new QueryRoot(parsed);
	}

	private static TupleExpr parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private static BindingSetAssignment countValues(Fixture fixture, int... counts) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("count"));
		List<BindingSet> rows = new ArrayList<>();
		for (int count : counts) {
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("count", fixture.store.getValueFactory().createLiteral(Integer.toString(count), CoreDatatype.XSD.INTEGER));
			rows.add(row);
		}
		values.setBindingSets(rows);
		return values;
	}

	private static List<String> values(List<BindingSet> rows, String name) {
		return rows.stream().map(row -> row.getValue(name).stringValue()).sorted().toList();
	}

	private static List<BindingSet> drain(QueryEvaluationStep step) {
		try (Opened rows = Transport.RDF.open(step)) {
			List<BindingSet> returned = new ArrayList<>();
			for (BindingSet row; (row = rows.next()) != null;) { returned.add(row); }
			return returned;
		}
	}

	private static void assertNativeGroup(Prepared prepared) {
		assertNotNull(prepared.group(), "the executed tree retains its real Group");
		String path = prepared.group().getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
		assertNotNull(path, "the Group in this same executed public root must report its actual route; step="
				+ prepared.step().getClass().getName());
		assertFalse(path.isBlank());
		assertNotEquals(LmdbNativeAttemptMetrics.PATH_GENERIC_FALLBACK, path);
	}

	private record Prepared(QueryRoot root, Group group, Filter filter, QueryEvaluationStep step) { }

	private interface Opened extends AutoCloseable {
		BindingSet next();
		NativeExecutionContext context();
		boolean cancel();
		@Override void close();
	}

	private static Opened open(Transport transport, QueryEvaluationStep step) {
		if (transport == Transport.TYPED_ADAPTER) {
			NativeResultCursor cursor = NativeResultSteps.open(step, input());
			return new Opened() {
				@Override public BindingSet next() {
					NativeResultRow row = cursor.next();
					return row == null ? null : row.toBindingSet();
				}
				@Override public NativeExecutionContext context() { return cursor.executionContext(); }
				@Override public boolean cancel() { return cursor.requestCancellation(); }
				@Override public void close() { cursor.close(); }
			};
		}
		CloseableIteration<BindingSet> rows = step.evaluate(input());
		return new Opened() {
			@Override public BindingSet next() { return rows.hasNext() ? rows.next() : null; }
			@Override public NativeExecutionContext context() { return NativeExecutionContextCarrier.contextOf(rows); }
			@Override public boolean cancel() {
				return rows instanceof CooperativeCancellation cancellation && cancellation.requestCancellation();
			}
			@Override public void close() { rows.close(); }
		};
	}

	private static final class Fixture implements AutoCloseable {
		final LmdbStore store;
		final SailRepository repository;
		final SailDataset dataset;
		final SailDatasetTripleTermSource source;
		final EvaluationStatistics statistics;
		final LmdbNativeEvaluationStrategy strategy;

		Fixture(File directory) throws Exception {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
					.setFrontierEstimatorMode(FrontierEstimatorMode.OFF).setOptimizerSamplingEnabled(false)
					.setBackgroundRawSamplingEnabled(false).setDirectAdjacencyEnabled(false).setValueOverlayEnabled(false);
			config.setExperimentalQueryOptimizations(true);
			store = new LmdbStore(directory, config);
			repository = new SailRepository(store);
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = store.getValueFactory();
				connection.begin();
				for (int index = 0; index < INPUTS; index++) {
					connection.add(vf.createIRI("urn:root-receipt:s:" + index), vf.createIRI("urn:root-receipt:p"),
							vf.createLiteral((index % 4 == 0 ? "hit:" : "miss:") + index));
				}
				connection.commit();
			}
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			dataset = NativeQuerySourceAccess.openExplicitDataset(store);
			source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			statistics = NativeQuerySourceAccess.evaluationStatistics(store);
			strategy = (LmdbNativeEvaluationStrategy) NativeQuerySourceAccess.evaluationStrategy(store, source, statistics);
			assertNoLearning();
		}

		List<BindingSet> ordinary(QueryRoot root) {
			DefaultEvaluationStrategy ordinary = new DefaultEvaluationStrategy(source, null, null, 0L,
					new EvaluationStatistics(), false);
			return drain(ordinary.precompileFinalTupleResult(root));
		}

		Prepared prepare(QueryRoot query, boolean summary) {
			QueryRoot root = assertInstanceOf(QueryRoot.class, strategy.optimize(query, statistics,
					EmptyBindingSet.getInstance()), "the Sail owning path retains the actual outer QueryRoot");
			Group[] group = { null };
			Filter[] filter = { null };
			root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override protected void meetNode(QueryModelNode node) {
					node.setExecutionSummaryEnabled(summary);
					super.meetNode(node);
				}
				@Override public void meet(Group node) {
					if (group[0] == null) { group[0] = node; }
					super.meet(node);
				}
				@Override public void meet(Filter node) {
					if (filter[0] == null) { filter[0] = node; }
					super.meet(node);
				}
			});
			assertNotNull(filter[0], "normal optimization retains the real residual FILTER population");
			return new Prepared(root, group[0], filter[0], strategy.precompileFinalTupleResult(root));
		}

		void assertNoLearning() {
			assertEquals(0, NativeQuerySourceAccess.learnedFilterCount(store));
		}

		void assertLearned(Filter filter, long inputs) {
			assertTrue(NativeQuerySourceAccess.learnedFilterCount(store) > 0,
					"the actual completed root must settle its selected native FILTER memo before publication");
			FilterPassEstimate estimate = statistics.estimateFilterPass(filter);
			assertEquals(FilterPassEstimate.Source.LEARNED_FILTER, estimate.getSource());
			assertEquals(0.25d, estimate.getPassRatio(), 0.0d);
			assertEquals(inputs, estimate.getEvidenceCount(), "only the complete selected logical census is reusable");
		}

		@Override public void close() {
			try { dataset.close(); } finally { repository.shutDown(); }
		}
	}
